/* Toolbox Learn 2.4.4 — uses the existing original project learning assets. */
(()=>{'use strict';
const root=document.getElementById('view');if(!root)return;
const sources=[['study','Maritime Study','maritime-study.json'],['cbt','Toolbox CBT','toolbox-cbt.json'],['speak','Communication Practice','articulation-presence.json']];
const data={};let section='hub',selected=null,question=0,chosen=null,answerShown=false,filter='all';
const key='toolbox-learn-progress-v244';let progress={};try{progress=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(key,JSON.stringify(progress))}catch{}}
function active(){return document.querySelector('nav [data-tab="learn"]')?.classList.contains('active')}
function list(){if(section==='study')return (data.study?.lessons||[]).filter(x=>filter==='all'||x.area===filter);if(section==='cbt')return data.cbt?.questions||[];return data.speak?.days||[]}
function title(x){return x.title||x.question||x.goal||('Day '+(x.day||x.number||''))}
function hub(){return `<div class="tl-head"><span class="tl-eyebrow">TOOLBOX ACADEMY</span><h1>Learn for your next watch.</h1><p>Practical maritime study you can continue offline.</p></div><div class="tl-grid">${sources.map(([id,label])=>`<button class="tl-course" data-tl-course="${id}"><span class="tl-symbol">${id==='study'?'01':id==='cbt'?'02':'03'}</span><strong>${label}</strong><small>${id==='study'?'Safety, deck, engine and vessel foundations':id==='cbt'?'Original maritime practice questions':'28-day articulation and presence program'}</small><span>Explore course →</span></button>`).join('')}</div><p class="tl-notice">Introductory study and practice only. Educator review is pending. Always follow current approved references and vessel procedures.</p>`}
function course(){const rows=list();let head=section==='study'?'Maritime Study':section==='cbt'?'Toolbox CBT':'Communication Practice';return `<button class="tl-back" data-tl-back>← All learning</button><div class="tl-head"><span class="tl-eyebrow">OFFLINE LEARNING</span><h1>${head}</h1><p>${section==='study'?'Choose a topic and work through its questions.':section==='cbt'?'Practice from the original Toolbox question bank.':'Build confidence with daily off-duty exercises.'}</p></div>${section==='study'?`<div class="tl-filters">${[['all','All'],...(data.study?.areas||[]).map(a=>[a.id,a.title])].map(([id,t])=>`<button data-tl-filter="${esc(id)}" class="${filter===id?'selected':''}">${esc(t)}</button>`).join('')}</div>`:''}<div class="tl-list">${rows.map((x,i)=>`<button class="tl-item" data-tl-item="${i}"><span><strong>${esc(title(x))}</strong><small>${esc(x.category||x.topicId||x.goal||x.subtitle||'Learning activity')}</small></span><span>${progress[section+':'+x.id]?'✓':'›'}</span></button>`).join('')}</div>${rows.length?'':'<p>No lessons found in this category.</p>'}<p class="tl-notice">${esc((data[section]||{}).notice||'Study material is for learning and review, not operational authorization.')}</p>`}
function lesson(){let x=selected;if(!x)return course();let qs=x.questions||(section==='cbt'?[{id:x.id,stem:x.question,options:x.options,answer:(x.answers||[])[0],explanation:x.explanation}]:[]);let q=qs[question];let body=section==='study'?`<p class="tl-goal">${esc(x.goal)}</p>${(x.notes||[]).map(n=>`<p>${esc(n)}</p>`).join('')}${x.scenario?`<div class="tl-scenario"><strong>Scenario</strong><p>${esc(x.scenario)}</p></div>`:''}${x.takeaway?`<p><strong>Takeaway:</strong> ${esc(x.takeaway)}</p>`:''}`:section==='speak'?`<p>${esc(x.goal||x.focus||x.description||'')}</p>${(x.steps||x.exercises||[]).map(n=>`<p>${esc(typeof n==='string'?n:JSON.stringify(n))}</p>`).join('')}`:'';
return `<button class="tl-back" data-tl-list>← Course topics</button><article class="tl-lesson"><span class="tl-eyebrow">${esc(x.category||'LEARNING SESSION')}</span><h1>${esc(title(x))}</h1>${body}${q?`<div class="tl-quiz"><strong>Question ${question+1} of ${qs.length}</strong><h3>${esc(q.stem||q.question)}</h3>${(q.options||[]).map((o,i)=>`<button data-tl-choice="${i}" class="${chosen===i?'selected':''}" ${answerShown?'disabled':''}>${esc(o)}</button>`).join('')}${answerShown?`<div class="tl-feedback"><strong>${chosen===q.answer?'Correct':'Review the answer'}</strong><p>${esc(q.explanation||'Refer to the course source material.')}</p></div>`:`<button class="tl-primary" data-tl-check ${chosen===null?'disabled':''}>Check answer</button>`}${answerShown?`<button class="tl-primary" data-tl-next>${question+1<qs.length?'Next question':'Complete lesson'}</button>`:''}</div>`:`<button class="tl-primary" data-tl-complete>Mark completed</button>`}</article><p class="tl-notice">${esc((data[section]||{}).notice||'Educational content; follow approved onboard procedures.')}</p>`}
function paint(){if(!active())return;root.innerHTML='<section class="tl-root">'+(section==='hub'?hub():selected?lesson():course())+'</section>';root.dataset.tlRendered='yes'}
async function load(){for(const [id,,file] of sources){try{let r=await fetch('assets/learning/'+file);if(!r.ok)throw Error();data[id]=await r.json()}catch{data[id]={notice:'Learning material unavailable. Reconnect once to download it.',lessons:[],questions:[],days:[]}}}if(active())paint()}
root.addEventListener('click',e=>{if(!active())return;const b=e.target.closest('[data-tl-course],[data-tl-back],[data-tl-filter],[data-tl-item],[data-tl-list],[data-tl-choice],[data-tl-check],[data-tl-next],[data-tl-complete]');if(!b)return;e.stopImmediatePropagation();if(b.hasAttribute('data-tl-course')){section=b.dataset.tlCourse;selected=null;filter='all'}else if(b.hasAttribute('data-tl-back')){section='hub';selected=null}else if(b.hasAttribute('data-tl-filter')){filter=b.dataset.tlFilter;selected=null}else if(b.hasAttribute('data-tl-item')){selected=list()[+b.dataset.tlItem];question=0;chosen=null;answerShown=false}else if(b.hasAttribute('data-tl-list')){selected=null}else if(b.hasAttribute('data-tl-choice'))chosen=+b.dataset.tlChoice;else if(b.hasAttribute('data-tl-check'))answerShown=true;else if(b.hasAttribute('data-tl-next')){let n=selected.questions?.length||1;if(question+1<n){question++;chosen=null;answerShown=false}else{progress[section+':'+selected.id]=Date.now();save();selected=null}}else if(b.hasAttribute('data-tl-complete')){progress[section+':'+selected.id]=Date.now();save();selected=null}paint()},true);
const observer=new MutationObserver(()=>{if(active()&&!root.querySelector('.tl-root'))paint()});observer.observe(root,{childList:true});document.querySelectorAll('nav [data-tab="learn"]').forEach(b=>b.addEventListener('click',()=>queueMicrotask(paint)));load();
})();
